L("Column 1: 4 × 1 = 4","stA",y=335,s=20,c=BL,x=310); L("Column 2: 4 × 2 = 8","stB",y=365,s=20,c=GR,x=450); L("Column 3: 4 × 4 = 16","stC",y=395,s=20,c=OR,x=590); L("4 + 8 + 16 = 28 sq m","stD",y=450,s=28,c=RD); L("Staircase: three steps, each 4 m wide, heights 1, 2 and 4 m","stT",y=70,s=22,c=BL)
T(S14,"m14-stairs","Another figure to split into rectangles: a staircase with three steps, each 4 metres wide, with heights of 1, 2 and 4 metres. Cut it into three tall rectangles. Their areas are 4 times 1, 4 times 2 and 4 times 4, that is 4, 8 and 16. Add them: 28 square metres.","செவ்வகங்களாகப் பிரிக்க இன்னொரு வடிவம்: ஒவ்வொன்றும் 4 மீ அகலம், 1, 2, 4 மீ உயரம் கொண்ட மூன்றுபடி. மூன்று செவ்வகங்களாகப் பிரியுங்கள். பரப்புகள் 4 × 1 = 4, 4 × 2 = 8, 4 × 4 = 16. கூட்டினால் 28 ச.மீ.",wr(["stT"],0.02,0)+sh(["st0","st1","st2"],0.1,0.15)+wr(["stA","stB","stC","stD"],0.55,0.12))
qs("m14-q2",S14,"A staircase has three steps, each 4 m wide, with heights 1 m, 2 m and 4 m. What is its area?","மூன்றுபடிகள், ஒவ்வொன்றும் 4 மீ அகலம், உயரம் 1, 2, 4 மீ. பரப்பு?","Add the three rectangles:","மூன்று செவ்வகங்களையும் கூட்டுங்கள்:",2,[O("12 sq m","12 ச.மீ","12 is just the width, 4 × 3.","12 என்பது 4 × 3 மட்டும்."),O("7 sq m","7 ச.மீ","7 adds the heights but forgets the width 4.","7 உயரங்களைக் கூட்டுகிறது, அகலம் 4 ஐ மறக்கிறது."),O("28 sq m","28 ச.மீ")],"4 × (1 + 2 + 4) = 28.","4 × (1 + 2 + 4) = 28.")
# tangram figure-it-out with the book's letters
qs("m14-t1",S14,"Tangram: the square D is made of the two small triangles C and E. How many times bigger is D than C?","டாங்கிராம்: சதுரம் D, சிறிய முக்கோணங்கள் C, E இரண்டாலும் ஆனது. D, C ஐ விட எத்தனை மடங்கு பெரியது?","D = C + E:","D = C + E:",1,[O("1 time","1 மடங்கு","D covers two small triangles, so it is bigger.","D இரண்டு சிறிய முக்கோணங்களை மூடுகிறது."),O("2 times","2 மடங்கு"),O("4 times","4 மடங்கு","4 times is a big triangle A or B.","4 மடங்கு பெரிய முக்கோணம் A அல்லது B.")],"C and E fit exactly on D: D = 2C.","C யும் E யும் D மேல் சரியாகப் பொருந்தும்: D = 2C.")
qs("m14-t2",S14,"Which has more area, the square D or the medium triangle F?","சதுரம் D, நடுத்தர முக்கோணம் F இவற்றில் பரப்பு அதிகம் எது?","Each equals two small triangles:","ஒவ்வொன்றும் இரண்டு சிறிய முக்கோணங்களுக்குச் சமம்:",2,[O("D","D","Both cover two small triangles.","இரண்டும் இரு சிறிய முக்கோணங்களை மூடும்."),O("F","F","Both cover two small triangles.","இரண்டும் இரு சிறிய முக்கோணங்களை மூடும்."),O("They are equal","சமம்")],"D = F = 2 units.","D = F = 2 அலகு.")
qs("m14-t3",S14,"The big triangle A compared to the parallelogram G: is A twice as big, or four times?","பெரிய முக்கோணம் A, இணைகரம் G உடன் ஒப்பிட: A இரு மடங்கா, நான்கு மடங்கா?","A = 4 units, G = 2 units:","A = 4 அலகு, G = 2 அலகு:",0,[O("Twice as big","இரு மடங்கு"),O("Four times as big","நான்கு மடங்கு","Four times would be 8 units.","நான்கு மடங்கு 8 அலகு."),O("Equal","சமம்","A is bigger than G.","A, G ஐ விடப் பெரியது.")],"4 ÷ 2 = 2.","4 ÷ 2 = 2.")
qs("m14-t4",S14,"The square made from all 7 pieces is how many times the area of the small triangle C?","7 துண்டுகளாலும் ஆன சதுரம் சிறிய முக்கோணம் C இன் எத்தனை மடங்கு?","Add 1+1+2+2+2+4+4:","1+1+2+2+2+4+4 ஐக் கூட்டுங்கள்:",2,[O("8 times","8 மடங்கு","8 is half of the total.","8 என்பது மொத்தத்தில் பாதி."),O("7 times","7 மடங்கு","7 counts the pieces, not their areas.","7 என்பது துண்டுகளின் எண்ணிக்கை, பரப்பு அல்ல."),O("16 times","16 மடங்கு")],"The total is 16 times C.","மொத்தம் C இன் 16 மடங்கு.")

