L("Charan: 35 ft × 30 ft","hcT1",y=100,s=22,c="#2E7D32",x=255); L("Sharan: 42 ft × 25 ft","hcT2",y=100,s=22,c="#E65100",x=680)
L("Area = 1050 sq ft","hcA1",y=290,s=26,c="#16253F",x=255); L("Area = 1050 sq ft","hcA2",y=290,s=26,c="#16253F",x=680)
