bI=mz("mb",[(3,0,2,5,"#FFFFFF","10 sq cm"),(0,5,5,2,"#FFFFFF","10 sq cm"),(5,0,3,3,PK,"? sq cm")],160,80,48,None)
L("Tall: 2 wide, 5 tall. Pink: 3 wide × (5 − 2) = 3 tall = 9 sq cm","mbU",y=450,s=17,c="#2E7D32")
step("pm-mazeb",S17,"Puzzle b. The bottom rectangle is 2 cm tall with area 10, so it is 5 cm wide. The 3 cm mark means the tall rectangle starts 3 cm from the left, so it is 5 minus 3, which is 2 cm wide. Its area is 10, so it is 10 divided by 2, which is 5 cm tall. The pink rectangle is 3 cm wide, and its height is 5 minus the 2 cm gap, which is 3 cm. So its area is 3 times 3, which is 9 square centimetres.","புதிர் b. கீழ்ச் செவ்வகம் 2 செ.மீ. உயரம், பரப்பு 10, எனவே அகலம் 5. 3 செ.மீ. குறி: உயரமான செவ்வகம் இடத்திலிருந்து 3 செ.மீ. தள்ளி; எனவே அகலம் 5 − 3 = 2. பரப்பு 10 ஆதலால் உயரம் 10 ÷ 2 = 5. இளஞ்சிவப்புச் செவ்வகம் அகலம் 3; உயரம் 5 − 2 = 3. பரப்பு 3 × 3 = 9 ச.செ.மீ.",[CL]+sh(bI,0.03,0.07,400)+wr(["mbU"],0.9,0))
qs("pm-qb",S17,"In puzzle b, what is the area of the pink rectangle?","புதிர் b இல் இளஞ்சிவப்புச் செவ்வகத்தின் பரப்பு?","Height 3, width 3:","உயரம் 3, அகலம் 3:",1,[O("6 sq cm","6 ச.செ.மீ.","The height is 3, not 2.","உயரம் 3, 2 அல்ல."),O("9 sq cm","9 ச.செ.மீ."),O("15 sq cm","15 ச.செ.மீ.","That uses the full height 5.","அது முழு உயரம் 5 ஐப் பயன்படுத்துகிறது.")],"3 × 3 = 9.","3 × 3 = 9.")
# c
cI=mz("mc",[(0,0,4,4,PK,"? sq cm"),(0,4,7,6,"#FFFFFF","42 sq cm"),(0,10,12,5,"#FFFFFF","60 sq cm")],200,40,26,None)
L("Middle 7 wide. Pink: 15 − 6 − 5 = 4 tall, 7 − 3 = 4 wide: 16 sq cm","mcU",y=470,s=17,c="#2E7D32")
step("pm-mazec",S17,"Puzzle c. The middle rectangle has area 42 and is 6 cm tall, so it is 7 cm wide. The whole figure is 15 cm tall, the bottom one is 5 cm tall and the middle 6, so the pink one is 15 minus 6 minus 5, which is 4 cm tall. The 3 cm mark shows the pink one is 3 cm narrower than the middle one, so it is 7 minus 3, which is 4 cm wide. Its area is 4 times 4, which is 16 square centimetres.","புதிர் c. நடுச் செவ்வகம் பரப்பு 42, உயரம் 6, எனவே அகலம் 7. முழு உயரம் 15; கீழ் 5, நடு 6; இளஞ்சிவப்பு உயரம் 15 − 6 − 5 = 4. 3 செ.மீ. குறி: இளஞ்சிவப்பு நடுவை விட 3 குறைவான அகலம்: 7 − 3 = 4. பரப்பு 4 × 4 = 16 ச.செ.மீ.",[CL]+sh(cI,0.03,0.07,400)+wr(["mcU"],0.9,0))
qs("pm-qc",S17,"In puzzle c, what is the area of the pink rectangle?","புதிர் c இல் இளஞ்சிவப்புச் செவ்வகத்தின் பரப்பு?","Find its height and width first:","முதலில் உயரம், அகலம் காணுங்கள்:",2,[O("12 sq cm","12 ச.செ.மீ.","The width is 4, not 3.","அகலம் 4, 3 அல்ல."),O("28 sq cm","28 ச.செ.மீ.","That is 4 × 7; the pink is only 4 wide.","அது 4 × 7; இளஞ்சிவப்பு 4 அகலம் மட்டுமே."),O("16 sq cm","16 ச.செ.மீ.")],"4 × 4 = 16.","4 × 4 = 16.")
# d
dI=mz("md",[(0,0,5,7.6,"#FFFFFF","38 sq cm"),(5,4,5,3.6,"#FFFFFF","18 sq cm")],220,70,40,None)
L("Right: 18 ÷ 5 = 3.6 tall, so the left is 4 + 3.6 = 7.6 tall. Width = 38 ÷ 7.6 = 5 cm","mdU",y=440,s=19,c="#2E7D32")
step("pm-mazed",S17,"Puzzle d. The bottom right rectangle is 5 cm wide with area 18, so it is 18 divided by 5, which is 3.6 cm tall. The left rectangle is 4 cm taller on top, so it is 7.6 cm tall. Its area is 38, so its width is 38 divided by 7.6, which is 5 cm.","புதிர் d. கீழ் வலச் செவ்வகம் அகலம் 5, பரப்பு 18; உயரம் 18 ÷ 5 = 3.6. இடச் செவ்வகம் மேலே 4 செ.மீ. அதிகம்: உயரம் 7.6. பரப்பு 38, எனவே அகலம் 38 ÷ 7.6 = 5 செ.மீ.",[CL]+sh(dI,0.03,0.1,400)+wr(["mdU"],0.9,0))
qs("pm-qd",S17,"In puzzle d, the left rectangle has area 38 sq cm and height 7.6 cm. What is its width?","புதிர் d இல் இடச் செவ்வகத்தின் பரப்பு 38 ச.செ.மீ., உயரம் 7.6 செ.மீ. அகலம்?","38 ÷ 7.6:","38 ÷ 7.6:",0,[O("5 cm","5 செ.மீ."),O("4 cm","4 செ.மீ.","4 × 7.6 is 30.4, not 38.","4 × 7.6 = 30.4, 38 அல்ல."),O("7.6 cm","7.6 செ.மீ.","That is the height, not the width.","அது உயரம், அகலம் அல்ல.")],"5 × 7.6 = 38.","5 × 7.6 = 38.")

S18="18 Grid figures"
GK=21; GX0=190; GY0=66
def gpt(c,r): return [round(GX0+c*GK,1),round(GY0+(r-2)*GK,1)]
shp={"a":[(3,4),(7,5),(7,11),(3,10)],"b":[(14,4),(10,7),(10,12),(14,14)],"c":[(16,4),(19,2),(22,4),(19,14),(16,12)],"d":[(5,15),(6,17),(9,15),(9,20),(5,20)],"e":[(17,15),(19,17),(18,21),(15,17)]}
# shift so a,d,e sit at left, b,c right: use as in the book
cols={"a":"#BBDEFB","b":"#C8E6C9","c":"#FFE0B2","d":"#E1BEE7","e":"#FFCDD2"}
for k,pts in shp.items():
    part("raw","gf"+k,{"kind":"poly","points":[gpt(*q) for q in pts],"fill":cols[k],"stroke":"#C0392B","width":4})
lab={"a":(5,7.5,"a  24"),"b":(12,9,"b  30"),"c":(19,8,"c  48"),"d":(7,18,"d  16"),"e":(17,18,"e  12")}
for k,(cx,cy,t) in lab.items(): L(t,"gl"+k,y=gpt(cx,cy)[1],s=22,c="#16253F",x=gpt(cx,cy)[0])
L("Find each area: draw a box around the figure, then cut off the corner triangles","gfT",y=40,s=20,c="#1E5FA8",x=450)
step("pm-grid",S18,"On grid paper, find the area of each figure by dividing it into rectangles and triangles. Draw a box around the figure, work out the box area, and subtract the corner triangles. For a: the box is 4 by 7, which is 28, and two corner triangles of 2 each, so 24. For b: box 4 by 10 is 40, minus triangles 6 and 4, so 30. For c: box 6 by 12 is 72, minus triangles 3, 3, 3 and 15, so 48. For d: box 4 by 5 is 20, minus the notch triangles 1 and 3, so 16. For e: box 4 by 6 is 24, minus triangles 2, 2, 2 and 6, so 12.","கட்டத் தாளில் ஒவ்வொரு உருவத்தின் பரப்பையும் செவ்வகங்களாகவும் முக்கோணங்களாகவும் பிரித்துக் காணுங்கள். உருவத்தைச் சுற்றி ஒரு பெட்டி வரைந்து, அதன் பரப்பிலிருந்து மூலை முக்கோணங்களைக் கழியுங்கள். a: பெட்டி 4 × 7 = 28, இரு முக்கோணங்கள் தலா 2: 24. b: 4 × 10 = 40 − 6 − 4 = 30. c: 6 × 12 = 72 − 3 − 3 − 3 − 15 = 48. d: 4 × 5 = 20 − 1 − 3 = 16. e: 4 × 6 = 24 − 2 − 2 − 2 − 6 = 12.",[CL]+wr(["gfT"],0.02,0)+[x for i,k in enumerate("abcde") for x in [["show","gf"+k,0.08+i*0.16,{"ms":400}],["write","gl"+k,0.14+i*0.16,{"ms":400}]]])
qs("pm-qg1",S18,"Figure a on the grid has a box of 4 by 7 and two corner triangles of area 2 each. What is its area?","கட்டத்தில் உருவம் a இன் பெட்டி 4 × 7; இரு மூலை முக்கோணங்கள் தலா 2. பரப்பு?","28 minus the two triangles:","28 இலிருந்து இரு முக்கோணங்களைக் கழியுங்கள்:",1,[O("28","28","That is the box, before subtracting.","அது பெட்டி; கழிக்கவில்லை."),O("24","24"),O("26","26","Two triangles of 2 take away 4, not 2.","தலா 2 உள்ள இரு முக்கோணங்கள் 4 கழிக்கும், 2 அல்ல.")],"28 − 2 − 2 = 24.","28 − 2 − 2 = 24.")
qs("pm-qg2",S18,"Figure c: box 6 by 12 = 72. The corner triangles are 3, 3, 3 and 15. What is the area?","உருவம் c: பெட்டி 6 × 12 = 72; மூலை முக்கோணங்கள் 3, 3, 3, 15. பரப்பு?","Add the triangles first: 24.","முதலில் முக்கோணங்களைக் கூட்டுங்கள்: 24.",0,[O("48","48"),O("54","54","That subtracts only 18.","அது 18 மட்டுமே கழிக்கிறது."),O("96","96","That adds the triangles instead of subtracting.","அது கழிக்காமல் கூட்டுகிறது.")],"72 − 24 = 48.","72 − 24 = 48.")
qs("pm-qg3",S18,"Which figure has the smallest area: a (24), b (30), d (16) or e (12)?","a (24), b (30), d (16), e (12) இவற்றில் மிகச் சிறிய பரப்பு எது?","Compare the four numbers:","நான்கு எண்களையும் ஒப்பிடுங்கள்:",3,[O("a","a","24 is bigger than 12.","24, 12 ஐ விடப் பெரியது."),O("b","b","30 is the biggest here.","30 இங்கே பெரியது."),O("d","d","16 is bigger than 12.","16, 12 ஐ விடப் பெரியது."),O("e","e")],"e has 12 sq units.","e இன் பரப்பு 12.")

